alter policy utility_meter_read on public.aqari_utility_meters using(private.aqari_can(workspace_id,'finance','read') and private.aqari_can(workspace_id,'properties','read')); alter policy utility_entry_read on public.aqari_utility_entries using(private.aqari_can(workspace_id,'finance','read') and private.aqari_can(workspace_id,'properties','read')); alter policy utility_entry_insert on public.aqari_utility_entries with check(private.aqari_can(workspace_id,'finance','write') and private.aqari_can(workspace_id,'properties','read') and recorded_by=(select auth.uid()) and entry_type in ('reading','bill'));
